-- Especies (102: 73 flora, 29 fauna).
INSERT INTO species (park_id, common_name, scientific_name, kingdom, family, primary_habitat, conservation_status,
    description, identification_tips, seasonality, image_url, image_attribution, latitude, longitude,
    rarity_score, is_featured, source, taxon_phylum, taxon_class, taxon_order, taxon_family, taxon_genus,
    iucn_global, spain_status, murcia_status, eidos_taxonid, gbif_species_key, zepa_site_code)
SELECT p.id, s.common_name, s.scientific_name, s.kingdom, s.family, s.primary_habitat, s.conservation_status,
    s.description, s.identification_tips, s.seasonality, s.image_url, s.image_attribution, s.latitude, s.longitude,
    s.rarity_score, s.is_featured, s.source, s.taxon_phylum, s.taxon_class, s.taxon_order, s.taxon_family, s.taxon_genus,
    s.iucn_global, s.spain_status, s.murcia_status, s.eidos_taxonid, s.gbif_species_key, s.zepa_site_code
FROM parks p
JOIN (
    SELECT 'Aulaga' common_name, 'Launaea arborescens' scientific_name, 'flora' kingdom, 'Mata' family, 'Matorral árido, ramblas y bordes de camino en clima muy seco' primary_habitat, 'En Peligro de Extinción' conservation_status, 'Mata en forma de bola formada por ramas verdes, rígidas y terminadas en pincho, casi sin hojas: la fotosíntesis la hacen los propios tallos. Al romper una rama suelta un látex blanco. Sus flores amarillas recuerdan a las del diente de león en miniatura.' description, 'Matorral redondo de ramas verdes y espinosas, casi sin hojas; Suelta látex blanco al partir un tallo; Flores amarillas tipo diente de león' identification_tips, 'Primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Launaea_arborescens_-_Oasis_Park_botanical_garden_-_Fuerteventura_-_02.jpg?width=1280' image_url, 'Norbert Nagel, Mörfelden-Walldorf, Germany (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 1 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 33 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Asterales' taxon_order, 'Asteraceae' taxon_family, 'Launaea' taxon_genus, 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)' iucn_global, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 9623 eidos_taxonid, 3144854 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Salao negro' common_name, 'Salsola oppositifolia' scientific_name, 'flora' kingdom, 'Mata' family, 'Ramblas, taludes y matorrales sobre suelos salinos o removidos, en clima muy seco' primary_habitat, 'No amenazada' conservation_status, 'Mata leñosa y ramosa, de hasta metro y medio, con hojas carnosas cortas y opuestas —de ahí el nombre— que dan a la planta un aspecto de escobilla gris azulada. Aguanta suelos salinos y alterados donde casi nada más prospera, y sus flores, diminutas, se reconocen porque el fruto queda envuelto en un ala membranosa circular.' description, 'Hojas carnosas y cortas dispuestas por pares, una frente a otra; Frutos con un ala redonda y translúcida, como una moneda de papel; Porte de escobilla gris azulada en taludes y bordes de rambla' identification_tips, 'Floración de verano a otoño' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Salsola_oppositifolia.JPG?width=1280' image_url, 'Retama (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 1 rarity_score, FALSE is_featured, 'Especie característica del hábitat de interés comunitario 1430 según el Atlas y Manual de los Hábitat de España (MITECO, 2005), con presencia confirmada por 20 ocurrencia(s) de GBIF dentro de ese hábitat en este espacio. La cita de GBIF figura como Soda oppositifolia.' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Caryophyllales' taxon_order, 'Amaranthaceae' taxon_family, 'Salsola' taxon_genus, 'No evaluada en la Lista Roja mundial de la UICN' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 7914 eidos_taxonid, 11364737 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Bolaga' common_name, 'Thymelaea hirsuta' scientific_name, 'flora' kingdom, 'Mata' family, 'Matorral costero y semiárido, arenas y suelos pedregosos con influencia marina' primary_habitat, 'No amenazada' conservation_status, 'Mata de ramas largas y flexibles cubiertas de hojitas escamosas, apretadas contra el tallo como las tejas de un tejado, con el envés blanco y peludo. Las flores son verdosas y pasan desapercibidas, pero su corteza es tan fibrosa y resistente que se ha usado tradicionalmente como cuerda.' description, 'Hojas minúsculas y solapadas, cubriendo el tallo como escamas; La rama no se rompe al doblarla: la corteza es fibrosa y correosa; Flores verde-amarillentas pegadas a la rama, sin pétalos vistosos' identification_tips, 'Floración de otoño a primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Thymelaea_hirsuta_Bonifacio.jpg?width=1280' image_url, 'Pancrat (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 1 rarity_score, FALSE is_featured, 'Presencia documentada por 17 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Malvales' taxon_order, 'Thymelaeaceae' taxon_family, 'Thymelaea' taxon_genus, 'No evaluada en la Lista Roja mundial de la UICN' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 8703 eidos_taxonid, 5523602 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Morsana' common_name, 'Zygophyllum fabago' scientific_name, 'flora' kingdom, 'Hierba' family, 'Suelos removidos, cunetas, ramblas y bordes de saladar en clima árido' primary_habitat, 'No amenazada' conservation_status, 'Hierba perenne de tallos gruesos y quebradizos con hojas carnosas partidas en dos folíolos redondeados, como dos gotas verdes enfrentadas. Coloniza suelos pisoteados y salinos, y sus frutos alargados, en forma de cápsula estriada, cuelgan durante buena parte del verano.' description, 'Hojas de solo dos folíolos carnosos y redondeados; Tallos hinchados en los nudos, que se quiebran con facilidad; Cápsulas alargadas y acostilladas colgando tras la floración' identification_tips, 'Floración de primavera a verano' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Morsana-1.JPG?width=1280' image_url, 'Philmarin (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 1 rarity_score, FALSE is_featured, 'Presencia documentada por 15 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Zygophyllales' taxon_order, 'Zygophyllaceae' taxon_family, 'Zygophyllum' taxon_genus, 'No evaluada en la Lista Roja mundial de la UICN' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 9448 eidos_taxonid, 3189902 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Cornical' common_name, 'Periploca angustifolia' scientific_name, 'flora' kingdom, 'Arbusto' family, 'Matorral cálido, laderas soleadas y barrancos de clima muy seco' primary_habitat, 'Vulnerable (Región de Murcia)' conservation_status, 'Arbusto de hojas estrechas y coriáceas y flores pequeñas con cinco pétalos de un pardo verdoso y aspecto aterciopelado. Sus frutos son dos vainas largas y curvas dispuestas en forma de cuerno, de donde le viene el nombre popular de cornical. Suelta látex al romperse.' description, 'Frutos en dos vainas curvas enfrentadas, como cuernos; Látex blanco al partir una hoja o rama; Flores pardo verdosas con aspecto de terciopelo' identification_tips, 'Primavera y verano (floración)' seasonality, 'https://inaturalist-open-data.s3.amazonaws.com/photos/609975159/original.jpg' image_url, 'Quentin Groom (CC0) · GBIF' image_attribution, NULL latitude, NULL longitude, 3 rarity_score, TRUE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 14 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO). La cita de GBIF figura como Periploca laevigata.' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Gentianales' taxon_order, 'Apocynaceae' taxon_family, 'Periploca' taxon_genus, 'NE (no evaluada a nivel global)' iucn_global, 'Pendiente de confirmar presencia y categoría en la Lista Roja de la Flora Vascular Española 2008' spain_status, 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)' murcia_status, 7034 eidos_taxonid, 6022574 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Sosa fina' common_name, 'Suaeda vera' scientific_name, 'flora' kingdom, 'Mata' family, 'Bordes de saladar y suelos salinos algo más secos y elevados' primary_habitat, 'Sensible a la alteración de su hábitat' conservation_status, 'Mata leñosa de hojas carnosas, cilíndricas y de un verde azulado, que ocupa la orla algo más alta y seca del saladar. Se diferencia de sus vecinas en que sí tiene hojas bien visibles y no tallos articulados. Sus flores son minúsculas y verdosas, en las axilas de las hojas.' description, 'Hojas carnosas y cilíndricas, verde azuladas; Base leñosa y ramificada, no herbácea; En la parte más seca y alta del saladar' identification_tips, 'Verano' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Suaeda_vera.JPG?width=1280' image_url, 'Xemenendura (CC BY-SA 4.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 11 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Caryophyllales' taxon_order, 'Amaranthaceae' taxon_family, 'Suaeda' taxon_genus, 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)' iucn_global, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 8507 eidos_taxonid, 6035538 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Cambrón' common_name, 'Lycium intricatum' scientific_name, 'flora' kingdom, 'Arbusto' family, 'Matorral costero y suelos salinos y nitrificados de clima cálido' primary_habitat, 'Especies de interés especial' conservation_status, 'Arbusto de ramas enmarañadas y espinosas, con hojitas carnosas agrupadas en manojos. Sus flores son pequeñas, tubulares y de color violeta pálido, y da bayas rojas que comen muchas aves. Forma setos impenetrables que dan refugio a pájaros y reptiles.' description, 'Ramas enredadas entre sí y terminadas en espina; Hojas carnosas en manojitos a lo largo de la rama; Bayas rojas pequeñas y flores tubulares violáceas' identification_tips, 'Todo el año' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lycium_intrincatum_(flor).JPG?width=1280' image_url, 'ANE (CC BY-SA 4.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 3 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 11 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Solanales' taxon_order, 'Solanaceae' taxon_family, 'Lycium' taxon_genus, 'NE (no evaluada a nivel global)' iucn_global, 'No confirmada presencia en la Lista Roja de la Flora Vascular Española 2008' spain_status, 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)' murcia_status, 5923 eidos_taxonid, 3796884 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Siempreviva insigne' common_name, 'Limonium insigne' scientific_name, 'flora' kingdom, 'Hierba' family, 'Suelos margosos y yesosos salinos, en estepas y taludes áridos' primary_habitat, 'Especies de interés especial' conservation_status, 'Una de las siemprevivas más vistosas: sus inflorescencias forman un ramillete denso de un lila rosado intenso que destaca sobre el gris de las margas. Es un endemismo del sureste ibérico, ligado a suelos salinos y yesosos, y muy usado en seco como flor ornamental.' description, 'Floración densa y de lila rosado vivo, muy llamativa; Hojas en roseta basal, gruesas y de borde ondulado; Sobre margas y yesos claros, en terreno casi desnudo' identification_tips, 'Final de primavera y verano' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Limonium_insigne.jpg?width=1280' image_url, 'ANE (CC BY-SA 4.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 4 rarity_score, TRUE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 10 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Caryophyllales' taxon_order, 'Plumbaginaceae' taxon_family, 'Limonium' taxon_genus, 'NE (no evaluada a nivel global; género con numerosos microendemismos ibéricos)' iucn_global, 'No localizada en la Lista Roja de la Flora Vascular Española 2008 con este nombre (pendiente de confirmar sinonimia)' spain_status, 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)' murcia_status, 5836 eidos_taxonid, 4088635 gbif_species_key, NULL zepa_site_code
