    SELECT 'Jarilla de Mota' common_name, 'Helianthemum motae' scientific_name, 'flora' kingdom, 'Mata' family, 'Matorrales abiertos y pastizales sobre suelos margosos y yesosos del sureste árido' primary_habitat, 'No amenazada' conservation_status, 'Jarilla pequeña y grisácea, de hojas estrechas cubiertas de pelo blanquecino que reflejan la luz y le ahorran agua. Es un endemismo del sureste ibérico de área muy reducida, ligado a los suelos margosos de las zonas más áridas de la península.' description, 'Mata baja de aspecto plateado por el fieltro de pelos; Flores amarillas de cinco pétalos que duran un solo día; Hojas estrechas y enrolladas hacia el envés' identification_tips, 'Floración en primavera' seasonality, 'https://inaturalist-open-data.s3.amazonaws.com/photos/640806369/original.jpg' image_url, 'faluke (CC BY-NC 4.0) · iNaturalist/GBIF' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Presencia documentada por 9 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Malvales' taxon_order, 'Cistaceae' taxon_family, 'Helianthemum' taxon_genus, 'No evaluada en la Lista Roja mundial de la UICN' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 31764 eidos_taxonid, 7661033 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Rugueta de mar' common_name, 'Cakile maritima' scientific_name, 'flora' kingdom, 'Hierba' family, 'Arena suelta de la primera línea de playa, sobre restos orgánicos del mar' primary_habitat, 'No amenazada' conservation_status, 'Crucífera anual y carnosa que coloniza la arena batida donde el mar deposita algas. Sus hojas son gruesas y recortadas y sus flores, lilas o blancas, tienen los cuatro pétalos en cruz de la familia. El fruto se parte en dos: una mitad queda en la planta y la otra flota y viaja por mar.' description, 'Hojas carnosas y recortadas, algo azuladas; Flores lilas o blancas de cuatro pétalos en cruz; Frutos duros en dos piezas, como pequeños barrilitos' identification_tips, 'Primavera a otoño' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cakile-maritima-(eurMeersenf)_1.jpg?width=1280' image_url, 'Jürgen Howaldt (CC BY-SA 2.0 de) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 1 rarity_score, FALSE is_featured, 'Presencia documentada por 9 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Brassicales' taxon_order, 'Brassicaceae' taxon_family, 'Cakile' taxon_genus, 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común litoral)' iucn_global, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 2937 eidos_taxonid, 3048831 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Margarita de mar' common_name, 'Asteriscus maritimus' scientific_name, 'flora' kingdom, 'Mata' family, 'Playas y dunas fósiles del litoral' primary_habitat, 'No amenazada' conservation_status, 'Mata que forma cojines sobre la roca litoral, con hojas espatuladas, carnosas y ásperas al tacto. Sus capítulos amarillos, casi sentados sobre el follaje, están rodeados de brácteas verdes que sobresalen entre las lígulas. Florece durante casi todo el año.' description, 'Cojines densos sobre roca costera; Brácteas verdes asomando entre los pétalos amarillos; Hojas espatuladas, carnosas y ásperas' identification_tips, 'Todo el año, floración prolongada' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Asteriscus_maritimus1.jpg?width=1280' image_url, 'Ximenex (CC BY-SA 2.1 es) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Presencia documentada por 8 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO). La cita de GBIF figura como Pallenis maritima.' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Asterales' taxon_order, 'Asteraceae' taxon_family, 'Asteriscus' taxon_genus, 'NE (no evaluada a nivel global)' iucn_global, 'No catalogada en la Lista Roja de la Flora Vascular Española 2008' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 9925 eidos_taxonid, 5385225 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Albardín' common_name, 'Lygeum spartum' scientific_name, 'flora' kingdom, 'Gramínea' family, 'Estepas salinas, margas y suelos yesosos secos; forma albardinales' primary_habitat, 'No amenazada' conservation_status, 'Gramínea perenne de hojas duras y punzantes que forma matas separadas sobre suelos salinos y margosos donde poco más prospera. Su inflorescencia es inconfundible: una espata blanca y sedosa que envuelve las flores como un capuchón de papel.' description, 'Espata blanca y sedosa envolviendo la espiga; Hojas rígidas terminadas en punta punzante; Matas espaciadas sobre suelo desnudo y claro' identification_tips, 'Todo el año (espigado en primavera)' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lygeum_spartum-1.jpg?width=1280' image_url, 'Nanosanchez (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 3 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 8 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Liliopsida' taxon_class, 'Poales' taxon_order, 'Poaceae' taxon_family, 'Lygeum' taxon_genus, 'LC' iucn_global, 'No catalogada en la Lista Roja de la Flora Vascular Española 2008' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 10060 eidos_taxonid, 2704651 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Jarilla de Almería' common_name, 'Helianthemum almeriense' scientific_name, 'flora' kingdom, 'Mata' family, 'Tomillares y matorral abierto sobre suelos secos y pedregosos' primary_habitat, 'No amenazada' conservation_status, 'Jarilla enana de hojas pequeñas y blanquecinas, cubiertas de pelos que reflejan la luz y reducen la pérdida de agua. En primavera se cubre de flores blancas con el centro amarillo, cuyos pétalos duran apenas una mañana. Sus raíces se asocian con hongos comestibles del desierto.' description, 'Mata baja y grisácea, de hojas muy pequeñas; Flores blancas con el centro amarillo, efímeras; Pétalos arrugados, como de papel de seda' identification_tips, 'Primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Helianthemum_almeriense_flor.jpg?width=1280' image_url, 'Retama (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 7 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Malvales' taxon_order, 'Cistaceae' taxon_family, 'Helianthemum' taxon_genus, 'No evaluada específicamente en la Lista Roja mundial de la UICN' iucn_global, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 4958 eidos_taxonid, 7331316 gbif_species_key, NULL zepa_site_code
