    SELECT 'Perfollada anual' common_name, 'Bupleurum semicompositum' scientific_name, 'flora' kingdom, 'Hierba' family, 'Pastizales anuales, claros de matorral y suelos margosos secos' primary_habitat, 'No amenazada' conservation_status, 'Umbelífera anual diminuta, de pocos centímetros, con hojas estrechas de un verde azulado y umbelas tan pequeñas que parecen botones. Es una de esas plantas efímeras que germinan con las lluvias, florecen deprisa y desaparecen antes del verano.' description, 'Planta anual muy pequeña, de aspecto rígido y verde azulado; Hojas lineares sin dientes, atravesadas por nervios paralelos; Umbelas minúsculas con brácteas que sobrepasan a las flores' identification_tips, 'Primavera' seasonality, 'https://observation.org/photos/125530399.jpg' image_url, 'Humedales de Navarra (CC BY-NC-ND 4.0) · observation.org / GBIF' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Presencia documentada por 4 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Apiales' taxon_order, 'Apiaceae' taxon_family, 'Bupleurum' taxon_genus, 'No evaluada en la Lista Roja mundial de la UICN' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 2852 eidos_taxonid, 3636403 gbif_species_key, NULL zepa_site_code
