    SELECT 'Anabasis' common_name, 'Anabasis hispanica' scientific_name, 'flora' kingdom, 'Planta suculenta' family, 'Suelos salinos y margosos áridos, estepas y ramblas de clima muy seco' primary_habitat, 'Especies de interés especial' conservation_status, 'Mata de tallos verdes, carnosos y articulados, sin hojas visibles, muy parecida a las sosas de saladar pero de porte más rígido y ramificado. Es una planta iberoafricana que en la península solo vive en los enclaves más áridos del sureste.' description, 'Tallos articulados y suculentos, sin hojas; Porte rígido y muy ramificado desde la base; En los suelos más áridos y salinos, casi desnudos' identification_tips, 'Verano y otoño' seasonality, 'https://observation.org/photos/111149341.jpg' image_url, 'Ans Gorter (CC BY-NC-ND 4.0) · observation.org / GBIF' image_attribution, NULL latitude, NULL longitude, 4 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 4 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO). La cita de GBIF figura como Anabasis articulata.' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Caryophyllales' taxon_order, 'Amaranthaceae' taxon_family, 'Anabasis' taxon_genus, 'NE' iucn_global, 'No localizada en la Lista Roja de la Flora Vascular Española 2008' spain_status, 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)' murcia_status, 1838 eidos_taxonid, 5568629 gbif_species_key, NULL zepa_site_code
