    SELECT 'Algazul' common_name, 'Mesembryanthemum nodiflorum' scientific_name, 'flora' kingdom, 'Planta suculenta' family, 'Saladares, arenas litorales y suelos salinos removidos' primary_habitat, 'No amenazada' conservation_status, 'Planta rastrera de hojas cilíndricas y carnosas cubiertas de papilas que brillan al sol como gotas de agua. Acumula sal en sus tejidos y, al secarse en verano, toma tonos rojizos que tiñen el suelo del saladar; se quemaba para obtener sosa, de ahí su nombre.' description, 'Hojas gruesas, cilíndricas y con aspecto escarchado; Porte tendido, formando alfombras pegadas al suelo; Vira a rojo intenso al agostarse, en pleno verano' identification_tips, 'Primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mesambryanthemum_nodiflorum.jpg?width=1280' image_url, 'Tigerente (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Caryophyllales' taxon_order, 'Aizoaceae' taxon_family, 'Mesembryanthemum' taxon_genus, 'No evaluada en la Lista Roja mundial de la UICN' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 6174 eidos_taxonid, 3084837 gbif_species_key, NULL zepa_site_code
