    SELECT 'Barrilla pinchosa' common_name, 'Salsola kali' scientific_name, 'flora' kingdom, 'Hierba' family, 'Arenas y gravas del primer cordón de playa y suelos removidos salinos' primary_habitat, 'No amenazada' conservation_status, 'Hierba anual muy ramificada, de hojas carnosas rematadas en un pincho fino, que forma una bola. Al secarse se desprende del suelo y rueda con el viento dispersando las semillas. Coloniza la línea donde el mar deja restos de algas y madera.' description, 'Hojas carnosas terminadas en una punta pinchuda; Forma una mata redondeada que rueda al secarse; Tallos con finas líneas rojizas o rosadas' identification_tips, 'Verano y otoño' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Salsola_kali_habito.jpg?width=1280' image_url, 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 1 rarity_score, FALSE is_featured, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Caryophyllales' taxon_order, 'Amaranthaceae' taxon_family, 'Salsola' taxon_genus, 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común litoral)' iucn_global, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 7912 eidos_taxonid, 3083957 gbif_species_key, NULL zepa_site_code
