    SELECT 'Bolina' common_name, 'Genista umbellata' scientific_name, 'flora' kingdom, 'Mata' family, 'Matorrales secos y soleados sobre suelos pobres del sureste ibérico' primary_habitat, 'Casi amenazada' conservation_status, 'Mata en forma de bola, densa y ramosa, con ramillas finas y estriadas que hacen la fotosíntesis porque las hojas duran muy poco. En pleno invierno se cubre de flores amarillas agrupadas en el extremo de las ramas, en umbelas apretadas.' description, 'Mata redondeada de ramillas verdes, finas y sin espinas; Flores amarillas reunidas al final de la rama, como un ramillete; Hojas diminutas y caedizas: casi siempre parece desnuda' identification_tips, 'Floración de invierno a primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Genista_umbellata.JPG?width=1280' image_url, 'Nanosanchez (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Fabales' taxon_order, 'Fabaceae' taxon_family, 'Genista' taxon_genus, 'NT — Casi amenazada (Lista Roja mundial de la UICN, 2021)' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 4925 eidos_taxonid, 8000707 gbif_species_key, NULL zepa_site_code
