    SELECT 'Cuchareta' common_name, 'Carrichtera annua' scientific_name, 'flora' kingdom, 'Hierba' family, 'Pastizales anuales, eriales y suelos margosos removidos en clima árido' primary_habitat, 'No amenazada' conservation_status, 'Crucífera anual de flores blanquecinas con nervios violáceos, inconfundible por su fruto: una vainita corta rematada por una lengüeta plana y curvada que recuerda a una cuchara. Los frutos secos persisten sobre la planta y son la mejor pista para identificarla.' description, 'Frutos con una pala plana en el extremo, como cucharillas; Hojas muy divididas, de segmentos estrechos; Planta anual pelosa, de pocos decímetros, en suelo pelado' identification_tips, 'Primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Carrichtera_annua2.JPG?width=1280' image_url, 'Flora y Vegetación de Lanzarote (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Brassicales' taxon_order, 'Brassicaceae' taxon_family, 'Carrichtera' taxon_genus, 'No evaluada en la Lista Roja mundial de la UICN' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 3176 eidos_taxonid, 5375285 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Fagonia' common_name, 'Fagonia cretica' scientific_name, 'flora' kingdom, 'Hierba' family, 'Suelos pedregosos, ramblas y litosuelos de clima árido' primary_habitat, 'No amenazada' conservation_status, 'Planta baja y tendida, de tallos angulosos, hojas divididas en tres y estípulas convertidas en espinas finas. Sus flores tienen cinco pétalos de un lila rosado que se abren durante las horas centrales del día. Es de estirpe norteafricana y aquí vive en el extremo de su área.' description, 'Porte tendido y desordenado, pegado al suelo; Hojas de tres foliolos con espinas en la base; Flores lila con cinco pétalos bien separados' identification_tips, 'Primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fagonia_cretica.jpg?width=1280' image_url, 'Retama (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 3 rarity_score, FALSE is_featured, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Zygophyllales' taxon_order, 'Zygophyllaceae' taxon_family, 'Fagonia' taxon_genus, 'No evaluada específicamente en la Lista Roja mundial de la UICN' iucn_global, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE; elemento iberoafricano de interés biogeográfico' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 4561 eidos_taxonid, 6384851 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Jarilla de brezo' common_name, 'Fumana ericoides' scientific_name, 'flora' kingdom, 'Mata' family, 'Matorrales y pastizales pedregosos sobre calizas, en solanas secas' primary_habitat, 'No amenazada' conservation_status, 'Matita leñosa de hojas estrechas y punzantes parecidas a las del brezo, de donde le viene el nombre. Sus flores amarillas, de cinco pétalos delicados, se abren por la mañana y pierden los pétalos el mismo día.' description, 'Hojas lineares, rígidas y puntiagudas, como agujas cortas; Flores amarillas efímeras, con pétalos arrugados; Mata baja y leñosa en la base, muy ramificada' identification_tips, 'Primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fumana_ericoides_Tallos_2010-7-03_ParqueNaturalLagunasdelaMata.jpg?width=1280' image_url, 'Javier martin (Public domain) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Malvales' taxon_order, 'Cistaceae' taxon_family, 'Fumana' taxon_genus, 'No evaluada en la Lista Roja mundial de la UICN' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 4652 eidos_taxonid, 8232802 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Uña de gato' common_name, 'Sedum sediforme' scientific_name, 'flora' kingdom, 'Planta suculenta' family, 'Prados calcáreos del Alysso-Sedion albi' primary_habitat, 'No amenazada' conservation_status, 'Crasulácea perenne de hojas suculentas puntiagudas y flores amarillo-verdosas, muy extendida por Murcia en repisas rocosas y prados calcáreos; especie característica del hábitat prioritario.' description, 'Hojas carnosas puntiagudas; Inflorescencia amarillo pálido; Coloniza repisas y suelos esqueléticos' identification_tips, 'Verano' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sedum_sediforme_hojas.jpg?width=1280' image_url, 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 1 rarity_score, FALSE is_featured, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO). La cita de GBIF figura como Petrosedum sediforme.' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Saxifragales' taxon_order, 'Crassulaceae' taxon_family, 'Sedum' taxon_genus, 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie muy común)' iucn_global, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 8225 eidos_taxonid, 4201784 gbif_species_key, NULL zepa_site_code
