    SELECT 'Cantueso dentado' common_name, 'Lavandula dentata' scientific_name, 'flora' kingdom, 'Mata aromática' family, 'Tomillares y matorral termomediterráneo' primary_habitat, 'No amenazada' conservation_status, 'Lavanda de hojas estrechas con el borde recortado en dientes redondeados, muy aromática. Su espiga violácea remata en un penacho de brácteas del mismo color, más corto que el del cantueso común. Florece durante buena parte del año en clima cálido.' description, 'Bordes de la hoja recortados en dientes romos; Penacho de brácteas violetas en lo alto de la espiga; Aroma intenso, entre lavanda y alcanfor' identification_tips, 'Primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lavandula_dentata1.jpg?width=1280' image_url, 'KENPEI (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 3 rarity_score, FALSE is_featured, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Lamiales' taxon_order, 'Lamiaceae' taxon_family, 'Lavandula' taxon_genus, 'NE' iucn_global, 'No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 5731 eidos_taxonid, 7307829 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Romerina' common_name, 'Cistus clusii' scientific_name, 'flora' kingdom, 'Mata' family, 'Tomillares y matorral seco sobre calizas y margas' primary_habitat, 'No amenazada' conservation_status, 'Jara pequeña de hojas muy estrechas y enrolladas por los bordes, verdes arriba y blancas por debajo, que a distancia recuerdan al romero. Se distingue enseguida al florecer: da grupos de flores blancas de cinco pétalos, mucho mayores que las del romero.' description, 'Hojas estrechas enrolladas, blancas por el envés; Flores blancas de cinco pétalos, varias juntas; Sin el olor a romero, aunque se le parezca de lejos' identification_tips, 'Primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cistus_clusii_(habitus).jpg?width=1280' image_url, 'Hans Hillewaert (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Malvales' taxon_order, 'Cistaceae' taxon_family, 'Cistus' taxon_genus, 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)' iucn_global, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 3610 eidos_taxonid, 7331346 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Albaida fina' common_name, 'Anthyllis terniflora' scientific_name, 'flora' kingdom, 'Mata' family, 'Matorrales áridos y espartales sobre suelos pobres del sureste ibérico' primary_habitat, 'No amenazada' conservation_status, 'Mata blanquecina, cubierta de pelos sedosos, con las flores agrupadas de tres en tres a lo largo de las ramas, que es lo que le da nombre. Es una leguminosa del extremo árido del sureste peninsular y del norte de África, adaptada a suelos yesosos y margas.' description, 'Flores en grupos de tres, dispuestas a lo largo de la rama; Follaje sedoso y plateado por el pelo tumbado; Cáliz hinchado y peludo que envuelve la flor' identification_tips, 'Floración de invierno a primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Anthyllis_terniflora_kz01.jpg?width=1280' image_url, 'Krzysztof Ziarnek, Kenraiz (CC BY-SA 4.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Fabales' taxon_order, 'Fabaceae' taxon_family, 'Anthyllis' taxon_genus, 'No evaluada en la Lista Roja mundial de la UICN' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 2192 eidos_taxonid, 5352344 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Escobilla' common_name, 'Salsola genistoides' scientific_name, 'flora' kingdom, 'Mata' family, 'Matorrales halo-nitrófilos' primary_habitat, 'No amenazada' conservation_status, 'Mata en forma de escoba, con ramas verdes, largas y erguidas, casi sin hojas, que florece a final de verano. Sus frutos van rodeados de alas membranosas rosadas que la vuelven muy vistosa en otoño. Es un endemismo del sureste ibérico.' description, 'Porte en escoba, con ramas verdes largas y erectas; Hojas reducidas casi a escamas; Frutos con alas membranosas rosadas en otoño' identification_tips, 'Verano y otoño' seasonality, 'https://inaturalist-open-data.s3.amazonaws.com/photos/474144349/original.jpeg' image_url, 'Gabriel Dixon (CC0) · GBIF' image_attribution, NULL latitude, NULL longitude, 3 rarity_score, FALSE is_featured, 'Especie característica del hábitat de interés comunitario 1430 según el Atlas y Manual de los Hábitat de España (MITECO, 2005), con presencia confirmada por 3 ocurrencia(s) de GBIF dentro de ese hábitat en este espacio. La cita de GBIF figura como Caroxylon genistoides.' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Caryophyllales' taxon_order, 'Amaranthaceae' taxon_family, 'Salsola' taxon_genus, 'NE' iucn_global, 'No incluida en el LESRPE; endemismo ibérico del sureste árido' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, NULL eidos_taxonid, 3759567 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Escarchada' common_name, 'Mesembryanthemum crystallinum' scientific_name, 'flora' kingdom, 'Planta suculenta' family, 'Suelos salinos y arenosos, taludes y bordes de saladar en clima cálido' primary_habitat, 'No amenazada' conservation_status, 'Planta carnosa y tendida cuyas hojas están cubiertas de vesículas transparentes llenas de agua salada: al sol parecen cristales de hielo o gotas de rocío que no se secan. Esas vesículas almacenan la sal que la planta extrae del suelo y le permiten vivir donde el terreno es demasiado salino para otras.' description, 'Hojas anchas cubiertas de ampollitas brillantes, como escarcha; Porte rastrero, formando manchas amplias sobre suelo desnudo; Tonos rosados o rojizos al final de su ciclo' identification_tips, 'Primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Unk_desert_flower_3.jpg?width=1280' image_url, 'Yummifruitbat (CC BY-SA 4.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Caryophyllales' taxon_order, 'Aizoaceae' taxon_family, 'Mesembryanthemum' taxon_genus, 'No evaluada en la Lista Roja mundial de la UICN' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 6172 eidos_taxonid, 3084839 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Cebolla albarrana' common_name, 'Squilla maritima' scientific_name, 'flora' kingdom, 'Planta bulbosa' family, 'Matorrales secos, laderas pedregosas y arenas litorales en clima cálido' primary_habitat, 'No amenazada' conservation_status, 'Bulbo enorme, del tamaño de un puño o mayor, que asoma medio enterrado y que en pleno agosto emite un tallo desnudo de más de un metro rematado por una larga espiga de flores blancas. Las hojas, anchas y correosas, aparecen después y desaparecen antes de florecer, así que rara vez se ven flores y hojas a la vez. Es tóxica y también se cita como Drimia maritima o Urginea maritima.' description, 'Bulbo grande y visible, asomando entre las piedras; Vara floral alta y desnuda, sin hojas, a final de verano; Roseta de hojas anchas y carnosas en invierno, sin flor' identification_tips, 'Hojas en invierno; floración a final de verano' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Young_Drimia_maritima%2C_near_Ramon_crater%2C_Israel.jpg?width=1280' image_url, 'Someone35 (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, TRUE is_featured, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO). La cita de GBIF figura como Drimia maritima.' source, 'Tracheophyta' taxon_phylum, 'Liliopsida' taxon_class, 'Asparagales' taxon_order, 'Asparagaceae' taxon_family, 'Squilla' taxon_genus, 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 9153 eidos_taxonid, 2776790 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Orgaza' common_name, 'Atriplex glauca' scientific_name, 'flora' kingdom, 'Mata' family, 'Matorrales halo-nitrófilos' primary_habitat, 'Protegida (LESRPE)' conservation_status, 'Mata baja y extendida, de hojas pequeñas, grisáceas y cubiertas de escamas harinosas que reflejan la luz. Marca los suelos con sal y exceso de nitrógeno, como los antiguos apriscos. Sus frutos van encerrados entre dos valvas endurecidas.' description, 'Hojas pequeñas, grises y harinosas al tacto; Porte bajo y muy extendido, casi tendido; Frutos entre dos valvas duras y dentadas' identification_tips, 'Verano' seasonality, 'https://inaturalist-open-data.s3.amazonaws.com/photos/611378691/original.jpg' image_url, 'Michael Bakker Paiva (CC BY 4.0) · GBIF' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Caryophyllales' taxon_order, 'Amaranthaceae' taxon_family, 'Atriplex' taxon_genus, 'LC' iucn_global, 'No incluida en el LESRPE; característica de matorrales halonitrófilos (HIC 1430)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 2639 eidos_taxonid, 7501008 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Cerraja fina' common_name, 'Sonchus tenerrimus' scientific_name, 'flora' kingdom, 'Hierba' family, 'Muros, taludes, cunetas y pies de roca en ambientes secos y alterados' primary_habitat, 'No amenazada' conservation_status, 'Cerraja de hojas muy divididas en segmentos estrechos, casi filiformes, que la distinguen de sus parientes de hoja ancha. Brota en cualquier grieta o talud, suelta látex blanco al partirla y florece prácticamente todo el año en clima cálido.' description, 'Hojas partidas en segmentos muy estrechos y separados; Látex blanco abundante al romper el tallo; Capítulos amarillo pálido y vilanos sedosos y blancos' identification_tips, 'Casi todo el año' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sonchus_tenerrimus_01.JPG?width=1280' image_url, 'Luca Fornasari (CC BY-SA 4.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Asterales' taxon_order, 'Asteraceae' taxon_family, 'Sonchus' taxon_genus, 'No evaluada en la Lista Roja mundial de la UICN' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 9686 eidos_taxonid, 3105768 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Cerrillo' common_name, 'Hyparrhenia hirta' scientific_name, 'flora' kingdom, 'Gramínea' family, 'Laderas secas, ribazos y pastizales sobre suelos pedregosos' primary_habitat, 'No amenazada' conservation_status, 'Gramínea perenne que forma matas y espiga en verano, cuando el resto del pastizal ya está agostado. Sus espiguillas van por parejas, cubiertas de pelos rojizos y con aristas retorcidas. Da al paisaje un tono dorado rojizo a final de verano.' description, 'Espiguillas peludas agrupadas por parejas; Aristas retorcidas y acodadas; Espiga en verano, cuando lo demás está seco' identification_tips, 'Verano y otoño' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hyparrhenia_hirta_Habitus_ValledeAlcudia.jpg?width=1280' image_url, 'Javier martin (Public domain) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 1 rarity_score, FALSE is_featured, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Liliopsida' taxon_class, 'Poales' taxon_order, 'Poaceae' taxon_family, 'Hyparrhenia' taxon_genus, 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)' iucn_global, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 10047 eidos_taxonid, 2703243 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Barba de chivo' common_name, 'Stipa capensis' scientific_name, 'flora' kingdom, 'Gramínea' family, 'Pastizales anuales sobre suelos secos y pedregosos' primary_habitat, 'No amenazada' conservation_status, 'Gramínea anual que agosta pronto y cubre los claros de matorral de un rubio pajizo. Cada semilla lleva una arista larga y retorcida que gira con los cambios de humedad y va enroscándose hasta clavarla en el suelo. Es la responsable de las «agujas» que se enganchan en los calcetines.' description, 'Aristas largas y retorcidas, en espiral al secarse; Planta anual: en verano queda seca y pajiza; Las semillas se clavan en la ropa y el pelaje' identification_tips, 'Primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stipa_capensis.JPG?width=1280' image_url, 'Juanmadro (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 1 rarity_score, FALSE is_featured, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO). La cita de GBIF figura como Stipellula capensis.' source, 'Tracheophyta' taxon_phylum, 'Liliopsida' taxon_class, 'Poales' taxon_order, 'Poaceae' taxon_family, 'Stipa' taxon_genus, 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)' iucn_global, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 10149 eidos_taxonid, 8315646 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Murajes' common_name, 'Lysimachia arvensis' scientific_name, 'flora' kingdom, 'Hierba' family, 'Cultivos, cunetas, claros y suelos removidos' primary_habitat, 'No amenazada' conservation_status, 'Hierbecilla tendida de tallos cuadrangulares y hojas enfrentadas, con flores solitarias que salen de la axila de cada hoja. Las hay de color naranja asalmonado y de color azul intenso, y ambas cierran los pétalos cuando el cielo se nubla, de ahí que se la llamara «hierba del buen tiempo».' description, 'Flores solitarias sobre un pedúnculo largo y fino; Tallos de sección cuadrada, tendidos por el suelo; Pétalos que se cierran al nublarse o a media tarde' identification_tips, 'Primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/A._arvensis-flor-1.JPG?width=1280' image_url, 'Philmarin (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Ericales' taxon_order, 'Primulaceae' taxon_family, 'Lysimachia' taxon_genus, 'No evaluada en la Lista Roja mundial de la UICN' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 80964 eidos_taxonid, 8184903 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Lastón' common_name, 'Brachypodium retusum' scientific_name, 'flora' kingdom, 'Gramínea' family, 'Pastizales, claros de matorral y ribazos sobre suelos calizos' primary_habitat, 'No amenazada' conservation_status, 'Gramínea perenne y rizomatosa que forma céspedes extensos en los claros del matorral mediterráneo. Sus hojas son cortas, rígidas y de punta roma. Es de las plantas que más rápido rebrota tras un incendio, gracias a sus rizomas subterráneos.' description, 'Céspedes extensos y bajos, no matas aisladas; Hojas cortas y rígidas, de punta redondeada; Espiguillas alineadas a un lado de un eje rígido' identification_tips, 'Primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Brachypodium_retusum_espiga_seca.jpg?width=1280' image_url, 'Pere prlpz (CC BY-SA 2.5) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 1 rarity_score, FALSE is_featured, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Liliopsida' taxon_class, 'Poales' taxon_order, 'Poaceae' taxon_family, 'Brachypodium' taxon_genus, 'LC (Preocupación menor)' iucn_global, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 9931 eidos_taxonid, 5676053 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Orgaza' common_name, 'Atriplex halimus' scientific_name, 'flora' kingdom, 'Arbusto' family, 'Suelos salinos y nitrificados, ramblas y bordes de saladar' primary_habitat, 'Protegida (LESRPE)' conservation_status, 'Arbusto de color gris plateado, cubierto de escamas microscópicas que reflejan la luz y ayudan a expulsar sal. Sus hojas son de forma romboidal y algo carnosas. Aguanta suelos que casi ninguna otra planta tolera, por lo que se usa para restaurar terrenos degradados.' description, 'Follaje gris plateado, harinoso al tacto; Hojas con forma de rombo o de punta de flecha; Frutos rodeados de dos valvas membranosas' identification_tips, 'Verano y otoño' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Atriplex_halimus_kz1.JPG?width=1280' image_url, 'Krzysztof Ziarnek, Kenraiz (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 1 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 2 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Caryophyllales' taxon_order, 'Amaranthaceae' taxon_family, 'Atriplex' taxon_genus, 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)' iucn_global, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 2712 eidos_taxonid, 3083718 gbif_species_key, NULL zepa_site_code
