    SELECT 'Colleja de arenal' common_name, 'Silene ramosissima' scientific_name, 'flora' kingdom, 'Hierba' family, 'Dunas con céspedes del Malcolmietalia' primary_habitat, 'En Peligro de Extinción' conservation_status, 'Colleja anual muy ramificada desde la base, característica de las dunas semifijas; da nombre a la asociación Triplachno nitentis-Silenetum ramosissimae.' description, 'Muy ramificada desde la base; Cáliz inflado con nervios marcados; Anual de vida corta' identification_tips, 'Primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Silene_ramosissima_2.jpg?width=1280' image_url, 'bymamo (CC BY-SA 4.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 3 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 2 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Caryophyllales' taxon_order, 'Caryophyllaceae' taxon_family, 'Silene' taxon_genus, 'No evaluada específicamente en la Lista Roja mundial de la UICN' iucn_global, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 8435 eidos_taxonid, 5584675 gbif_species_key, NULL zepa_site_code
