    SELECT 'Rubia marina' common_name, 'Crucianella maritima' scientific_name, 'flora' kingdom, 'Mata' family, 'Dunas y arenas litorales estabilizadas' primary_habitat, 'Sensible a la alteración de su hábitat' conservation_status, 'Matita rígida de las arenas costeras, con las hojas dispuestas en verticilos de cuatro que envuelven el tallo formando una columna geométrica de un verde glauco. Sus flores amarillentas se abren en espigas terminales apretadas, y sus tallos leñosos fijan la arena a su alrededor.' description, 'Hojas en anillos de cuatro alrededor del tallo, muy regulares; Aspecto rígido y azulado, casi de plástico, sobre arena; Espigas terminales de flores pequeñas y amarillentas' identification_tips, 'Primavera y principio de verano' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Crucianella_maritima_1.JPG?width=1280' image_url, 'Gideon Pisanty (Gidip) גדעון פיזנטי (CC BY 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 2 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Gentianales' taxon_order, 'Rubiaceae' taxon_family, 'Crucianella' taxon_genus, 'No evaluada en la Lista Roja mundial de la UICN' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 3764 eidos_taxonid, 5336649 gbif_species_key, NULL zepa_site_code
