    SELECT 'Acebuche' common_name, 'Olea europaea var. sylvestris' scientific_name, 'flora' kingdom, 'Árbol' family, 'Matorral alto, laderas secas y barrancos del piso más cálido' primary_habitat, 'No amenazada' conservation_status, 'El acebuche es el olivo silvestre: mismo árbol, sin siglos de selección. Tiene las hojas más pequeñas y duras, las ramas jóvenes a menudo espinosas y aceitunas diminutas. Forma matorrales altos y es el árbol característico de las laderas cálidas mediterráneas.' description, 'Hojas pequeñas, verdes arriba y plateadas por debajo; Ramillas jóvenes rígidas y a veces espinosas; Aceitunas muy pequeñas, de poco más de un centímetro' identification_tips, 'Todo el año' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ullastre_vell.JPG?width=1280' image_url, 'Antoni Salvà (CC BY-SA 4.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 2 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO). La cita de GBIF figura como Olea europaea.' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Lamiales' taxon_order, 'Oleaceae' taxon_family, 'Olea' taxon_genus, 'LC' iucn_global, 'No catalogada en la Lista Roja de la Flora Vascular Española 2008' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 6644 eidos_taxonid, 5415040 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Albaida' common_name, 'Anthyllis cytisoides' scientific_name, 'flora' kingdom, 'Mata' family, 'Matorral seco y soleado sobre margas y suelos pobres' primary_habitat, 'Protegida (LESRPE)' conservation_status, 'Mata de aspecto blanquecino por la fina pelusa que cubre hojas y tallos, un recurso frente al sol y la sequía. En primavera se llena de espigas de flores amarillas que atraen a muchos insectos. Es una de las leguminosas que primero coloniza laderas degradadas y taludes.' description, 'Aspecto grisáceo y aterciopelado al tacto; Flores amarillas pequeñas en espigas apretadas; Hojas divididas en tres, la del centro más larga' identification_tips, 'Primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Anthyllis_cytisoides.JPG?width=1280' image_url, 'Ximenex (CC BY-SA 2.1 es) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 1 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 2 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Fabales' taxon_order, 'Fabaceae' taxon_family, 'Anthyllis' taxon_genus, 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie muy común)' iucn_global, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 2186 eidos_taxonid, 5352466 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Boja negra' common_name, 'Artemisia barrelieri' scientific_name, 'flora' kingdom, 'Mata aromática' family, 'Matorrales halo-nitrófilos' primary_habitat, 'No amenazada' conservation_status, 'Mata aromática grisácea de las bojas del sureste árido, colonizadora de suelos alterados, bordes de camino y matorrales nitrificados.' description, 'Olor aromático fuerte al frotar; Follaje gris-plateado; Indica suelos alterados' identification_tips, 'Otoño' seasonality, 'https://inaturalist-open-data.s3.amazonaws.com/photos/173279674/original.jpeg' image_url, 'Yamil J.R (CC0) · GBIF' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie característica del hábitat de interés comunitario 1430 según el Atlas y Manual de los Hábitat de España (MITECO, 2005), con presencia confirmada por 2 ocurrencia(s) de GBIF dentro de ese hábitat en este espacio.' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Asterales' taxon_order, 'Asteraceae' taxon_family, 'Artemisia' taxon_genus, 'NE' iucn_global, 'No incluida en el LESRPE; característica de matorrales halonitrófilos (HIC 1430)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 9913 eidos_taxonid, 3120786 gbif_species_key, NULL zepa_site_code
