    SELECT 'Acelguilla espinosa' common_name, 'Limonium echioides' scientific_name, 'flora' kingdom, 'Hierba' family, 'Pastizales secos, suelos margosos y salinos en clima árido' primary_habitat, 'No amenazada' conservation_status, 'Saladilla anual pequeña, con una roseta de hojas ásperas al tacto y tallos ramificados en zigzag que llevan las flores en espiguillas cortas. Las flores, blanquecinas o violáceas, conservan el cáliz seco y papiráceo mucho después de marchitarse.' description, 'Hojas de la roseta ásperas, con pelillos duros; Tallos en zigzag, con ramas divaricadas; Cálices secos y papiráceos persistiendo tras la flor' identification_tips, 'Primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Limonium_echioides233.JPG?width=1280' image_url, 'Nanosanchez (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 2 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Caryophyllales' taxon_order, 'Plumbaginaceae' taxon_family, 'Limonium' taxon_genus, 'No evaluada en la Lista Roja mundial de la UICN' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 5805 eidos_taxonid, 4090024 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Campanica' common_name, 'Convolvulus althaeoides' scientific_name, 'flora' kingdom, 'Hierba' family, 'Ribazos, cunetas, cultivos y claros de matorral' primary_habitat, 'No amenazada' conservation_status, 'Correhuela trepadora de flores rosadas grandes y llamativas, con hojas muy variables: las de abajo casi enteras y las de arriba profundamente divididas y plateadas. Se enreda en la vegetación de ribazos y márgenes.' description, 'Flores rosa intenso en embudo, grandes y vistosas; Hojas superiores muy recortadas y de aspecto plateado; Tallos volubles que se enredan en otras plantas' identification_tips, 'Primavera y verano' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Convolvulus_althaeoides_1.JPG?width=1280' image_url, 'User:Xemenendura (CC BY-SA 2.1 es) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 1 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 2 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Solanales' taxon_order, 'Convolvulaceae' taxon_family, 'Convolvulus' taxon_genus, 'No evaluada específicamente en la Lista Roja mundial de la UICN' iucn_global, 'Sin figura de protección nacional específica registrada en EIDOS' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 3692 eidos_taxonid, 2928400 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Siempreviva de Cosson' common_name, 'Limonium cossonianum' scientific_name, 'flora' kingdom, 'Hierba' family, 'Saladares, acantilados costeros y suelos salinos margosos' primary_habitat, 'Especies de interés especial' conservation_status, 'Siempreviva de roseta basal de hojas espatuladas y tallos ramificados que sostienen espiguillas de flores diminutas de color lila. Los cálices secos y papiráceos permanecen en la planta hasta el invierno siguiente, dando al saladar un tono pajizo persistente.' description, 'Roseta basal de hojas anchas y espatuladas; Ramificación en zigzag, muy abierta; Cálices secos que persisten meses tras florecer' identification_tips, 'Verano' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Limonium_cossonianum.jpg?width=1280' image_url, 'Nanosanchez (CC0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 3 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Caryophyllales' taxon_order, 'Plumbaginaceae' taxon_family, 'Limonium' taxon_genus, 'NE' iucn_global, 'No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)' spain_status, 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)' murcia_status, 5761 eidos_taxonid, 7297983 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Sosa blanca' common_name, 'Suaeda maritima' scientific_name, 'flora' kingdom, 'Hierba' family, 'Marismas, saladares y orillas de aguas salobres' primary_habitat, 'Sensible a la alteración de su hábitat' conservation_status, 'Hierba anual de hojas cilíndricas y carnosas que crece en los suelos más encharcados y salinos del saladar, donde el agua sube y baja. Al final del ciclo toma tonos rojizos o purpúreos que delatan su presencia a distancia.' description, 'Hojas carnosas, cilíndricas y de punta roma; Flores diminutas y verdosas en la axila de las hojas; Coloración rojiza al final del verano, en suelo salino húmedo' identification_tips, 'Verano y otoño' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Suaeda_maritima_01_by_Line1.JPG?width=1280' image_url, 'Liné1 (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Caryophyllales' taxon_order, 'Amaranthaceae' taxon_family, 'Suaeda' taxon_genus, 'No evaluada en la Lista Roja mundial de la UICN' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 8514 eidos_taxonid, 3083541 gbif_species_key, NULL zepa_site_code
