    SELECT 'Grama de arena' common_name, 'Ammochloa palaestina' scientific_name, 'flora' kingdom, 'Gramínea' family, 'Arenas litorales y suelos sueltos y secos' primary_habitat, 'Especies de interés especial' conservation_status, 'Gramínea anual enana que forma una mata apretada a ras de suelo, con la inflorescencia reducida a una cabezuela compacta casi sin tallo, medio escondida entre las hojas. Vive en arenas móviles, donde su ciclo relámpago aprovecha la humedad de las lluvias.' description, 'Inflorescencia en cabezuela apretada, casi sentada sobre la mata; Planta enana, de pocos centímetros, sobre arena suelta; Hojas cortas y rígidas, agrupadas en la base' identification_tips, 'Primavera' seasonality, NULL image_url, NULL image_attribution, NULL latitude, NULL longitude, 3 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Liliopsida' taxon_class, 'Poales' taxon_order, 'Poaceae' taxon_family, 'Ammochloa' taxon_genus, 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2013)' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)' murcia_status, 9756 eidos_taxonid, 4106283 gbif_species_key, NULL zepa_site_code
