    SELECT 'Ajo porro' common_name, 'Allium subvillosum' scientific_name, 'flora' kingdom, 'Planta bulbosa' family, 'Arenas litorales, pastizales secos y claros de matorral' primary_habitat, 'En Peligro de Extinción' conservation_status, 'Ajo silvestre de flores blancas agrupadas en una umbela laxa sobre un tallo fino, con las hojas estrechas y con el borde y el nervio ligeramente pelosos. Como todos los ajos, delata su identidad en cuanto se estruja una hoja.' description, 'Umbela de flores blancas con nervio verdoso en cada pétalo; Hojas estrechas con pelillos en el margen; Olor claro a ajo al frotar las hojas o el bulbo' identification_tips, 'Primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Allium_subvillosum.JPG?width=1280' image_url, 'Xemenendura (CC BY-SA 4.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Liliopsida' taxon_class, 'Asparagales' taxon_order, 'Amaryllidaceae' taxon_family, 'Allium' taxon_genus, 'No evaluada en la Lista Roja mundial de la UICN' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 2031 eidos_taxonid, 2857317 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Algarrobo' common_name, 'Ceratonia siliqua' scientific_name, 'flora' kingdom, 'Árbol' family, 'Laderas cálidas, antiguos cultivos y matorral del piso termomediterráneo' primary_habitat, 'Protegida (LESRPE)' conservation_status, 'Árbol perennifolio de copa densa y hojas compuestas con foliolos redondeados y lustrosos. Florece en otoño directamente sobre el tronco y las ramas viejas. Sus vainas pardas y dulces, las algarrobas, se han usado durante siglos como pienso y alimento.' description, 'Hojas compuestas de foliolos redondos y brillantes; Flores nacidas directamente del tronco y las ramas gruesas; Vainas pardas y aplanadas colgando del árbol' identification_tips, 'Todo el año' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ceratonia_siliqua_Keciboynuzu_1370984_Nevit.jpg?width=1280' image_url, 'Nevit Dilmen (talk) (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Fabales' taxon_order, 'Fabaceae' taxon_family, 'Ceratonia' taxon_genus, 'LC (Preocupación menor) (evaluación UICN 2017)' iucn_global, 'ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 3422 eidos_taxonid, 5356354 gbif_species_key, NULL zepa_site_code
