    SELECT 'Cerraja gaditana' common_name, 'Reichardia gaditana' scientific_name, 'flora' kingdom, 'Hierba' family, 'Arenas litorales, suelos salinos y eriales cercanos a la costa' primary_habitat, 'No amenazada' conservation_status, 'Pariente cercana del cerrajón, anual y de hojas carnosas abrazadas al tallo, con capítulos amarillos y látex blanco. Es propia de suelos arenosos y algo salinos del suroeste y del sureste peninsular.' description, 'Hojas basales carnosas, con dientes anchos y triangulares; Capítulos amarillos con brácteas de borde membranoso; Látex blanco al partir cualquier parte de la planta' identification_tips, 'Primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Reichardia_gaditana_2.JPG?width=1280' image_url, 'Xemenendura (CC BY-SA 4.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Asterales' taxon_order, 'Asteraceae' taxon_family, 'Reichardia' taxon_genus, 'No evaluada en la Lista Roja mundial de la UICN' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 638 eidos_taxonid, 5385653 gbif_species_key, NULL zepa_site_code
