    SELECT 'Eslizón ibérico' common_name, 'Chalcides bedriagai' scientific_name, 'fauna' kingdom, 'Reptil' family, 'Matorral termomediterráneo semiárido' primary_habitat, 'Vulnerable' conservation_status, 'Eslizón de cuerpo cilíndrico y brillante, con las patas tan reducidas que apenas se usan: se desplaza reptando y buceando entre la arena y la hojarasca. Su dorso, dorado o bronceado, lleva hileras de ocelos oscuros con el centro claro.' description, 'Patas diminutas, casi inútiles para caminar; Cuerpo cilíndrico y muy brillante, como pulido; Hileras de ocelos oscuros de centro claro en el dorso' identification_tips, 'Primavera y verano' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Chalcides_bedriagai_01_by-dpc.jpg?width=1280' image_url, 'David Perez (CC BY 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 4 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Chordata' taxon_phylum, 'Reptilia' taxon_class, 'Squamata' taxon_order, 'Scincidae' taxon_family, 'Chalcides' taxon_genus, 'LC' iucn_global, 'LESRPE; Directiva Hábitats 92/43/CEE, Anexo IV' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 10827 eidos_taxonid, 8974077 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Helianthemum viscarium' common_name, 'Helianthemum viscarium' scientific_name, 'flora' kingdom, 'Mata' family, 'Tomillares y matorral raso sobre margas y suelos yesosos' primary_habitat, 'No amenazada' conservation_status, 'Jarilla pequeña y pegajosa, con hojas estrechas y tallos cubiertos de pelos glandulosos que retienen el polvo. Sus flores amarillas duran apenas unas horas y se renuevan cada día. Es un endemismo del sureste ibérico ligado a suelos margosos.' description, 'Tallos pegajosos, con polvo y arena adheridos; Flores amarillas efímeras, de un solo día; Sobre margas y yesos, en terreno claro' identification_tips, 'Primavera' seasonality, 'https://inaturalist-open-data.s3.amazonaws.com/photos/384325778/original.jpg' image_url, 'anarkis (CC BY-NC 4.0) · GBIF/iNaturalist' image_attribution, NULL latitude, NULL longitude, 1 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Malvales' taxon_order, 'Cistaceae' taxon_family, 'Helianthemum' taxon_genus, 'No evaluada específicamente en la Lista Roja mundial de la UICN' iucn_global, 'Sin figura de protección nacional específica registrada en EIDOS' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 5103 eidos_taxonid, 7331463 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Cardo mancaperros' common_name, 'Eryngium ilicifolium' scientific_name, 'flora' kingdom, 'Hierba' family, 'Pastizales secos, eriales y suelos margosos pisoteados' primary_habitat, 'No amenazada' conservation_status, 'Cardo corredor anual, muy espinoso y rígido, con hojas duras parecidas a las de la encina —de ahí el nombre— y cabezuelas espinosas azuladas rodeadas de brácteas punzantes. Al secarse se vuelve leñoso y persiste todo el verano pinchando a quien pase.' description, 'Hojas rígidas y espinosas, recortadas como las de la encina; Cabezuelas con brácteas largas y punzantes en estrella; Tonos azulados en las brácteas durante la floración' identification_tips, 'Primavera y verano' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Eryngium_ilicifolium_InflorescenceCloseup2_DehesaBoyaldePuertollano.jpg?width=1280' image_url, 'Javier martin (Public domain) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Apiales' taxon_order, 'Apiaceae' taxon_family, 'Eryngium' taxon_genus, 'No evaluada en la Lista Roja mundial de la UICN' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 4406 eidos_taxonid, 3630524 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Cosco' common_name, 'Aizoanthemopsis hispanica' scientific_name, 'flora' kingdom, 'Planta suculenta' family, 'Suelos salinos y margosos desnudos, en depresiones áridas' primary_habitat, 'No amenazada' conservation_status, 'Anual carnosa y tendida, cubierta de papilas que le dan aspecto áspero y blanquecino, con flores pequeñas sin pétalos que se abren estrelladas al sol. Es una planta de los suelos más pobres y salinos, donde forma manchas dispersas sobre el barro desnudo.' description, 'Ramas carnosas y tendidas, ásperas y grisáceas; Flores sin pétalos, con sépalos que se abren en estrella; Crece sobre suelo desnudo, salino o margoso' identification_tips, 'Primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Aizoon_hispanicum_2b.JPG?width=1280' image_url, 'Ghislain118 https://www.fleurs-des-montagnes.net (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Caryophyllales' taxon_order, 'Aizoaceae' taxon_family, 'Aizoanthemopsis' taxon_genus, 'No evaluada en la Lista Roja mundial de la UICN' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 1811 eidos_taxonid, 9819723 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Crásula enana' common_name, 'Crassula tillaea' scientific_name, 'flora' kingdom, 'Planta suculenta' family, 'Claros arenosos y suelos someros que se encharcan brevemente en invierno' primary_habitat, 'No amenazada' conservation_status, 'Una de las plantas con flor más pequeñas de la península: apenas un centímetro de tallos carnosos con hojitas apretadas en pares, que al madurar se tiñen de rojo intenso y colorean el suelo. Hay que agacharse mucho para verla, pero cuando abunda pinta manchas rojizas inconfundibles.' description, 'Planta minúscula, de menos de dos centímetros; Hojas carnosas opuestas y apretadas a lo largo del tallo; Vira a rojo intenso al madurar, tiñendo el suelo' identification_tips, 'Final de invierno y primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Crassula_connata.jpg?width=1280' image_url, 'Mike (CC BY-SA 4.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Saxifragales' taxon_order, 'Crassulaceae' taxon_family, 'Crassula' taxon_genus, 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2013)' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 3849 eidos_taxonid, 5362055 gbif_species_key, NULL zepa_site_code
