    SELECT 'Erodio' common_name, 'Erodium sanguis-christi' scientific_name, 'flora' kingdom, 'Hierba' family, 'Litosuelos y pastizales abiertos' primary_habitat, 'Especies de interés especial' conservation_status, 'Pequeña geraniácea anual de suelos abiertos y pedregosos, de floración temprana en el piso termomediterráneo semiárido.' description, 'Flores rosadas pequeñas; Fruto con pico alargado característico de Erodium; Anual de suelos pedregosos' identification_tips, 'Primavera' seasonality, 'https://inaturalist-open-data.s3.amazonaws.com/photos/642301345/original.jpg' image_url, 'Laia Lahoz (CC BY-NC 4.0) · iNaturalist/GBIF' image_attribution, NULL latitude, NULL longitude, 4 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Geraniales' taxon_order, 'Geraniaceae' taxon_family, 'Erodium' taxon_genus, 'NE' iucn_global, 'No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)' spain_status, 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)' murcia_status, 9835 eidos_taxonid, 7268491 gbif_species_key, NULL zepa_site_code
