    SELECT 'Grama salada' common_name, 'Sphenopus divaricatus' scientific_name, 'flora' kingdom, 'Gramínea' family, 'Saladares, depresiones salinas y suelos arcillosos con sal' primary_habitat, 'No amenazada' conservation_status, 'Gramínea anual delicada, de tallos finísimos y panícula muy abierta con las ramas separadas casi en ángulo recto, que en conjunto parece una nube. Es una de las pocas gramíneas capaces de completar su ciclo en los suelos salinos del saladar.' description, 'Panícula muy abierta, con ramas separadas en ángulo recto; Planta anual grácil, de tallos capilares; Espiguillas diminutas en el extremo de las ramas' identification_tips, 'Primavera' seasonality, 'https://observation.org/photos/125538681.jpg' image_url, 'Humedales de Navarra (CC BY-NC-ND 4.0) · observation.org / GBIF' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie característica del hábitat de interés comunitario  según el Atlas y Manual de los Hábitat de España (MITECO, 2005), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de ese hábitat en este espacio.' source, 'Tracheophyta' taxon_phylum, 'Liliopsida' taxon_class, 'Poales' taxon_order, 'Poaceae' taxon_family, 'Sphenopus' taxon_genus, 'No evaluada en la Lista Roja mundial de la UICN' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 10143 eidos_taxonid, 4153196 gbif_species_key, NULL zepa_site_code
