    SELECT 'Canadillo' common_name, 'Ephedra fragilis' scientific_name, 'flora' kingdom, 'Arbusto' family, 'Roquedos, matorral seco y pie de acantilado en clima cálido' primary_habitat, 'Protegida (LESRPE)' conservation_status, 'Arbusto de aspecto extraño: un manojo de tallos verdes, articulados y colgantes, casi sin hojas, que se quiebran con facilidad por los nudos. No es una planta con flores, sino un pariente lejano de las coníferas; sus semillas van envueltas en una cubierta roja y carnosa.' description, 'Tallos verdes articulados que se rompen por los nudos; Sin hojas visibles, solo escamas en cada nudo; Frutos rojos carnosos con una semilla dentro' identification_tips, 'Primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ephedra_fragilis_3.JPG?width=1280' image_url, 'User:falconaumanni (CC BY-SA 4.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Gnetopsida' taxon_class, 'Ephedrales' taxon_order, 'Ephedraceae' taxon_family, 'Ephedra' taxon_genus, 'LC (Preocupación menor)' iucn_global, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 4308 eidos_taxonid, 2653414 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Oroval' common_name, 'Withania frutescens' scientific_name, 'flora' kingdom, 'Arbusto' family, 'Matorral cálido, roquedos y ramblas de clima muy seco' primary_habitat, 'Protegida (LESRPE)' conservation_status, 'Arbusto de la familia del tomate y la belladona, con hojas ovaladas algo carnosas y flores verdosas discretas. Los frutos son bayas rojas y brillantes envueltas en el cáliz. Es una especie de raíz norteafricana que en la península solo vive en los rincones más cálidos del sureste.' description, 'Bayas rojas pequeñas asomando del cáliz; Hojas ovales, algo carnosas y de verde apagado; Flores verde amarillentas, poco vistosas' identification_tips, 'Primavera y otoño' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Withania_frutescens0176.jpg?width=1280' image_url, 'Nanosanchez (CC BY-SA 4.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 3 rarity_score, FALSE is_featured, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Solanales' taxon_order, 'Solanaceae' taxon_family, 'Withania' taxon_genus, 'No evaluada específicamente en la Lista Roja mundial de la UICN' iucn_global, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE; elemento iberoafricano de interés biogeográfico' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 9438 eidos_taxonid, 3801152 gbif_species_key, NULL zepa_site_code
