    SELECT 'Alcaraván' common_name, 'Burhinus oedicnemus' scientific_name, 'fauna' kingdom, 'Ave esteparia' family, 'Llanos pedregosos, cultivos de secano, ramblas y eriales con poca cobertura' primary_habitat, 'En Peligro de Extinción' conservation_status, 'Ave de aspecto extraño y ojos amarillos enormes, adaptados a la actividad nocturna. De día permanece agachada e inmóvil, confiada en su plumaje críptico, y solo al anochecer se activa y delata con un reclamo silbado y melancólico que recuerda al del zarapito.' description, 'Ojos amarillos desproporcionadamente grandes; Dos barras blancas y negras en el ala plegada; Reclamo silbado y triste al anochecer' identification_tips, 'Todo el año' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Burhinus_oedicnemus_insularum_Lanzarote_1.jpg?width=1280' image_url, 'Frank Vassen from Brussels, Belgium (CC BY 2.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 3 rarity_score, FALSE is_featured, 'Especie de la lista oficial del sitio Natura 2000 ES6200010 (EEA/BISE, Site_Species_List). Confirmada además por 3 ocurrencias de GBIF dentro de este espacio.' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, 'Charadriiformes' taxon_order, 'Burhinidae' taxon_family, 'Burhinus' taxon_genus, 'LC' iucn_global, 'LESRPE; Directiva Aves 2009/147/CE, Anexo I' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 11887 eidos_taxonid, NULL gbif_species_key, 'ES6200010' zepa_site_code
    UNION ALL
    SELECT 'Chotacabras cuellirrojo' common_name, 'Caprimulgus ruficollis' scientific_name, 'fauna' kingdom, 'Ave' family, 'Matorral abierto, pinares aclarados, ramblas y caminos térreos' primary_habitat, 'Protegida (LESRPE)' conservation_status, 'Ave crepuscular de plumaje jaspeado que imita la hojarasca, tan mimético que de día resulta casi imposible verla posada en el suelo. Caza polillas en vuelo con la boca muy abierta. Su canto nocturno es un «cu-toc, cu-toc» repetido de forma monótona durante minutos.' description, 'Collar rojizo en la nuca, más marcado que en su pariente europeo; Se levanta del camino al anochecer y vuelve a posarse unos metros más allá; Canto nocturno monótono, como un motor lejano' identification_tips, 'Primavera y verano (estival)' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Caprimulgus_ruficollis_-Portugal-8.jpg?width=1280' image_url, 'Olivença (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 3 rarity_score, FALSE is_featured, 'Especie de la lista oficial del sitio Natura 2000 ES6200010 (EEA/BISE, Site_Species_List). Confirmada además por 3 ocurrencias de GBIF dentro de este espacio.' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, NULL taxon_order, NULL taxon_family, 'Caprimulgus' taxon_genus, 'NT (Casi amenazado)' iucn_global, 'Directiva Aves 2009/147/CE (Red Natura 2000); LESRPE' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 12122 eidos_taxonid, NULL gbif_species_key, 'ES6200010' zepa_site_code
    UNION ALL
    SELECT 'Carraca europea' common_name, 'Coracias garrulus' scientific_name, 'fauna' kingdom, 'Ave' family, 'Campos abiertos con arbolado disperso, ribazos y construcciones con huecos' primary_habitat, 'Vulnerable' conservation_status, 'Del tamaño de una paloma y de un azul turquesa intenso que sorprende al levantar el vuelo. Caza al acecho desde cables y postes, dejándose caer sobre saltamontes y escarabajos. Cría en huecos de árboles viejos y de edificios, de ahí que dependa de que queden árboles añosos y ruinas en el campo.' description, 'Azul turquesa que solo se aprecia bien cuando vuela; Espalda de color canela que contrasta con el azul; Posada quieta en cables, oteando el suelo' identification_tips, 'Primavera y verano (estival)' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/European_roller.jpg?width=1280' image_url, 'Christian Svane (CC BY-SA 2.5) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie de la lista oficial del sitio Natura 2000 ES6200010 (EEA/BISE, Site_Species_List). Sin ocurrencia de GBIF verificada dentro del espacio: la cita es documental.' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, NULL taxon_order, NULL taxon_family, 'Coracias' taxon_genus, 'LC (Preocupación menor)' iucn_global, 'LESRPE (RD 139/2011); Directiva Aves 2009/147/CE; Ley 42/2007, Anexo IV' spain_status, 'Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)' murcia_status, 11339 eidos_taxonid, NULL gbif_species_key, 'ES6200010' zepa_site_code
    UNION ALL
    SELECT 'Garceta común' common_name, 'Egretta garzetta' scientific_name, 'fauna' kingdom, 'Ave acuática' family, 'Marismas, salinas, ramblas con agua, arrozales y orillas costeras' primary_habitat, 'Sensible a la alteración de su hábitat' conservation_status, 'Garza blanca y esbelta, de tamaño medio, con el pico negro y las patas negras rematadas en unos pies amarillos llamativos. Pesca removiendo el fondo con esas patas para levantar peces y camarones. En época de cría luce dos plumas largas y finas en la nuca.' description, 'Pies amarillos al final de patas negras; Pico negro y fino, no amarillo; Remueve el fondo con una pata mientras acecha' identification_tips, 'Todo el año' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Aigrette_garzette_au_lac_sud_de_Tunis_(site_RAMSAR).jpg?width=1280' image_url, 'El Golli Mohamed (CC BY-SA 4.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie de la lista oficial del sitio Natura 2000 ES6200010 (EEA/BISE, Site_Species_List). Confirmada además por 70 ocurrencias de GBIF dentro de este espacio.' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, NULL taxon_order, NULL taxon_family, 'Egretta' taxon_genus, 'LC (Preocupación menor)' iucn_global, 'Directiva Aves 2009/147/CE (Red Natura 2000)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 11340 eidos_taxonid, NULL gbif_species_key, 'ES6200010' zepa_site_code
    UNION ALL
    SELECT 'Halcón peregrino' common_name, 'Falco peregrinus' scientific_name, 'fauna' kingdom, 'Ave rapaz' family, 'Cortados y áreas abiertas' primary_habitat, 'Vulnerable' conservation_status, 'Halcón robusto de alas puntiagudas y cola corta, capaz de superar los 300 km/h en el picado con que abate a otras aves en pleno vuelo. Se reconoce por la ancha bigotera negra que baja desde el ojo sobre un pecho claro y barrado.' description, 'Bigotera negra ancha bajo el ojo, como un casco; Silueta de ancla: alas puntiagudas y cola corta; Pecho claro con barrado fino en horizontal' identification_tips, 'Todo el año' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Falco_peregrinus_-_01.jpg?width=1280' image_url, 'Carlos Delgado (CC BY-SA 4.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 4 rarity_score, FALSE is_featured, 'Especie de la lista oficial del sitio Natura 2000 ES6200010 (EEA/BISE, Site_Species_List). Confirmada además por 18 ocurrencias de GBIF dentro de este espacio.' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, 'Falconiformes' taxon_order, 'Falconidae' taxon_family, 'Falco' taxon_genus, 'LC' iucn_global, 'LESRPE; Directiva Aves 2009/147/CE, Anexo I; Reglamento CITES (CE) 338/97, Anexo A' spain_status, 'Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)' murcia_status, 11963 eidos_taxonid, NULL gbif_species_key, 'ES6200010' zepa_site_code
    UNION ALL
    SELECT 'Cigüeñuela' common_name, 'Himantopus himantopus' scientific_name, 'fauna' kingdom, 'Ave limícola' family, 'Salinas, marismas, charcas someras y humedales salobres' primary_habitat, 'Vulnerable' conservation_status, 'Limícola blanca y negra de patas rosadas larguísimas, desproporcionadas para su tamaño, que le permiten caminar por aguas someras picoteando insectos en la superficie. Es ruidosa y muy territorial cerca del nido, y sobrevuela en círculos a quien se acerca.' description, 'Patas rojizas extremadamente largas, que sobresalen en vuelo; Contraste limpio de blanco y negro, con pico fino y recto; Reclamo insistente y chillón al sobrevolar al intruso' identification_tips, 'Sobre todo de primavera a verano' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Himantopus_himantopus.jpg?width=1280' image_url, '(Hans Hillewaert) (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie de la lista oficial del sitio Natura 2000 ES6200010 (EEA/BISE, Site_Species_List). Confirmada además por 3 ocurrencias de GBIF dentro de este espacio.' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, 'Charadriiformes' taxon_order, 'Recurvirostridae' taxon_family, 'Himantopus' taxon_genus, 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)' iucn_global, 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011) · Anexo IV (Ley 42/2007, de 13 de diciembre, del Patrimonio Natural y de la Biodiversidad. BOE 299, de 14 de diciembre de 2007)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 11446 eidos_taxonid, NULL gbif_species_key, 'ES6200010' zepa_site_code
    UNION ALL
    SELECT 'Collalba negra' common_name, 'Oenanthe leucura' scientific_name, 'fauna' kingdom, 'Ave' family, 'Matorral litoral, laderas secas y roquedos' primary_habitat, 'En Peligro de Extinción' conservation_status, 'La mayor de las collalbas, enteramente negra salvo el obispillo y la base de la cola, blancos. Vive en cortados y laderas rocosas, donde construye junto al nido una plataforma de piedrecitas que acarrea una a una. Su canto es potente y melodioso.' description, 'Cuerpo negro con obispillo blanco muy contrastado; «T» negra invertida en la cola blanca al volar; Montoncitos de piedrecitas junto a la grieta del nido' identification_tips, 'Todo el año' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Black_Wheatear%2C_Isla_Plana_3.jpg?width=1280' image_url, 'Andrew Thomas from Shrewsbury, UK (CC BY-SA 2.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 3 rarity_score, FALSE is_featured, 'Especie de la lista oficial del sitio Natura 2000 ES6200010 (EEA/BISE, Site_Species_List). Confirmada además por 306 ocurrencias de GBIF dentro de este espacio.' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, 'Passeriformes' taxon_order, 'Muscicapidae' taxon_family, 'Oenanthe' taxon_genus, 'LC' iucn_global, 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial); Directiva Aves 2009/147/CE, Anexo I' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 11592 eidos_taxonid, NULL gbif_species_key, 'ES6200010' zepa_site_code
    UNION ALL
    SELECT 'Tórtola europea' common_name, 'Streptopelia turtur' scientific_name, 'fauna' kingdom, 'Ave' family, 'Sotos, arboledas y matorral alto junto a cultivos y ramblas' primary_habitat, 'En Peligro de Extinción' conservation_status, 'La más pequeña y grácil de nuestras palomas, con el dorso escamado en negro y canela y un parche a rayas blancas y negras en el cuello. Su arrullo ronco y adormecedor es uno de los sonidos del verano. Sus poblaciones han caído mucho en Europa por la pérdida de barbechos y setos.' description, 'Espalda escamada, como un mosaico canela y negro; Parche rayado blanco y negro a los lados del cuello; Arrullo ronco y vibrante, muy distinto al de la tórtola turca' identification_tips, 'Primavera y verano (estival)' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Streptopelia_turtur_Grlica0036.jpg?width=1280' image_url, 'Zrno at Serbian Wikipedia (Public domain) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 4 rarity_score, FALSE is_featured, 'Especie de la lista oficial del sitio Natura 2000 ES6200010 (EEA/BISE, Site_Species_List). Confirmada además por 6 ocurrencias de GBIF dentro de este espacio.' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, NULL taxon_order, NULL taxon_family, 'Streptopelia' taxon_genus, 'VU (Vulnerable)' iucn_global, 'No incluida en el LESRPE; Directiva Aves 2009/147/CE, Anexo II (especie cinegética); Reglamento CITES, Anexo A' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 12356 eidos_taxonid, NULL gbif_species_key, 'ES6200010' zepa_site_code
    UNION ALL
    SELECT 'Charrancito común' common_name, 'Sternula albifrons' scientific_name, 'fauna' kingdom, 'Ave marina' family, 'Playas de arena y grava, salinas y lagunas costeras' primary_habitat, 'Vulnerable' conservation_status, 'El más pequeño de los charranes europeos, con la frente blanca y el pico amarillo de punta negra. Cría directamente sobre la arena o la grava, en nidos que son poco más que un hoyo, lo que lo hace muy sensible al tránsito de personas en las playas.' description, 'Frente blanca que contrasta con el capirote negro; Pico amarillo con la punta negra; Se ciñe sobre el agua antes de zambullirse en picado' identification_tips, 'Primavera y verano (estival)' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Little_Tern_6820C.jpg?width=1280' image_url, 'Little_Tern_6820.jpg: Alnus derivative work: Osado (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 3 rarity_score, FALSE is_featured, 'Especie de la lista oficial del sitio Natura 2000 ES6200010 y ES0000507 (EEA/BISE, Site_Species_List). Sin ocurrencia de GBIF verificada dentro del espacio: la cita es documental.' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, 'Charadriiformes' taxon_order, 'Laridae' taxon_family, 'Sternula' taxon_genus, 'LC' iucn_global, 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial); Directiva Aves 2009/147/CE, Anexo I' spain_status, 'Vulnerable (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)' murcia_status, 14084 eidos_taxonid, NULL gbif_species_key, 'ES0000507' zepa_site_code
    UNION ALL
    SELECT 'Alca común' common_name, 'Alca torda' scientific_name, 'fauna' kingdom, 'Ave marina' family, 'Mar abierto y aguas costeras fuera de la época de cría' primary_habitat, 'Vulnerable' conservation_status, 'Ave marina compacta, negra por arriba y blanca por debajo, con un pico grueso y comprimido lateralmente cruzado por una línea blanca. Vuela bajo y rápido, rozando el agua, y bucea propulsándose con las alas para perseguir peces pequeños.' description, 'Pico grueso y aplanado de lado, con una raya blanca vertical; Vuelo rápido a ras de agua, con aleteo rígido; Se zambulle desde la superficie, sin lanzarse desde el aire' identification_tips, 'Invierno' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Razorbill_iceland.JPG?width=1280' image_url, 'autor no indicado (Public domain) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Confirmada además por 36 ocurrencias de GBIF dentro de este espacio.' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, 'Charadriiformes' taxon_order, 'Alcidae' taxon_family, 'Alca' taxon_genus, 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2021)' iucn_global, 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 14089 eidos_taxonid, NULL gbif_species_key, 'ES0000507' zepa_site_code
