    SELECT 'Pardela cenicienta mediterránea' common_name, 'Calonectris diomedea' scientific_name, 'fauna' kingdom, 'Ave marina' family, 'Mar abierto; cría en islotes e islas del Mediterráneo' primary_habitat, 'Vulnerable (Región de Murcia)' conservation_status, 'Pardela grande de dorso pardo ceniciento y vientre blanco, con pico amarillento, que planea largamente sobre las olas alternando ascensos y descensos casi sin batir las alas. Cría en colonias en islotes rocosos y se acerca a ellos de noche, con reclamos que recuerdan a un llanto.' description, 'Vuelo planeado en arcos largos, casi sin aletear; Dorso pardo ceniciento sin capucha oscura marcada; Pico amarillento con la punta oscura' identification_tips, 'De primavera a otoño' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/CorysShearwaterBottom.jpg?width=1280' image_url, 'TomAllmendinger (CC BY 2.5) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 4 rarity_score, FALSE is_featured, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Sin ocurrencia de GBIF verificada dentro del espacio: la cita es documental.' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, 'Procellariiformes' taxon_order, 'Procellariidae' taxon_family, 'Calonectris' taxon_genus, 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)' iucn_global, 'Anexo IV (Ley 42/2007, de 13 de diciembre, del Patrimonio Natural y de la Biodiversidad. BOE 299, de 14 de diciembre de 2007)' spain_status, 'Vulnerable (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)' murcia_status, 11166 eidos_taxonid, NULL gbif_species_key, 'ES0000507' zepa_site_code
