    SELECT 'Paíño europeo' common_name, 'Hydrobates pelagicus' scientific_name, 'fauna' kingdom, 'Ave marina' family, 'Mar abierto; cría en grietas y cuevas de islotes' primary_habitat, 'Anexo I' conservation_status, 'El ave marina más pequeña del Mediterráneo, apenas del tamaño de un gorrión, negruzca con una banda blanca muy marcada en la rabadilla. Revolotea a ras de agua como una mariposa, con las patas colgando y rozando la superficie.' description, 'Tamaño diminuto, negruzco, con obispillo blanco evidente; Vuelo aleteado y errático, casi pegado al agua; Patas colgando que rozan la superficie al alimentarse' identification_tips, 'Sobre todo de primavera a otoño' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hydrobates_pelagicus.jpg?width=1280' image_url, 'Júlio Reis (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 4 rarity_score, FALSE is_featured, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Sin ocurrencia de GBIF verificada dentro del espacio: la cita es documental.' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, 'Procellariiformes' taxon_order, 'Hydrobatidae' taxon_family, 'Hydrobates' taxon_genus, 'VU — Vulnerable (Lista Roja mundial de la UICN, 1992)' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 11953 eidos_taxonid, NULL gbif_species_key, 'ES0000507' zepa_site_code
    UNION ALL
    SELECT 'Gaviota de Audouin' common_name, 'Larus audouinii' scientific_name, 'fauna' kingdom, 'Ave marina' family, 'Islotes y costas mediterráneas; pesca en mar abierto cerca de la orilla' primary_habitat, 'Anexo II. Lista de especies en peligro o amenazadas.' conservation_status, 'Gaviota mediterránea de tamaño medio, elegante y de aspecto más «limpio» que la patiamarilla, con el pico rojo coral anillado de negro y las patas verdosas oscuras. Pesca al vuelo rozando el agua, sobre todo de noche y de madrugada. Cría en colonias muy concentradas en islotes y salinas.' description, 'Pico rojo coral con una banda negra cerca de la punta; Patas verde oscuro, no amarillas; Ojo oscuro que le da expresión suave' identification_tips, 'Todo el año, con concentraciones en verano' seasonality, 'https://inaturalist-open-data.s3.amazonaws.com/photos/611415320/original.jpg' image_url, 'Michael Bakker Paiva (CC BY 4.0) · GBIF' image_attribution, NULL latitude, NULL longitude, 4 rarity_score, TRUE is_featured, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Sin ocurrencia de GBIF verificada dentro del espacio: la cita es documental.' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, NULL taxon_order, NULL taxon_family, 'Larus' taxon_genus, 'VU (Vulnerable)' iucn_global, 'Catálogo Español de Especies Amenazadas (CEEA): Vulnerable; Ley 42/2007, Anexo IV' spain_status, 'Vulnerable (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)' murcia_status, 14053 eidos_taxonid, NULL gbif_species_key, 'ES0000507' zepa_site_code
    UNION ALL
    SELECT 'Gaviota sombría' common_name, 'Larus fuscus' scientific_name, 'fauna' kingdom, 'Ave marina' family, 'Costas, puertos, playas y vertederos, sobre todo en invierno' primary_habitat, 'Anexo II' conservation_status, 'Gaviota grande de dorso gris oscuro o casi negro y patas amarillas, que cría en el norte de Europa e inverna en gran número en las costas ibéricas. Se mezcla con la patiamarilla, de la que se distingue por el manto mucho más oscuro y el porte algo más estilizado.' description, 'Manto gris pizarra oscuro, mucho más que en la patiamarilla; Patas amarillas y pico amarillo con mancha roja; Presente sobre todo en invierno, en bandos mixtos' identification_tips, 'Otoño e invierno' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Larus-fuscus-taxbox.jpg?width=1280' image_url, 'Andreas Trepte (CC BY-SA 2.5) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Confirmada además por 11 ocurrencias de GBIF dentro de este espacio.' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, 'Charadriiformes' taxon_order, 'Laridae' taxon_family, 'Larus' taxon_genus, 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)' iucn_global, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 14057 eidos_taxonid, NULL gbif_species_key, 'ES0000507' zepa_site_code
    UNION ALL
    SELECT 'Gaviota cabecinegra' common_name, 'Larus melanocephalus' scientific_name, 'fauna' kingdom, 'Ave marina' family, 'Costas, playas, salinas y lagunas litorales' primary_habitat, 'Anexo II. Lista de especies en peligro o amenazadas.' conservation_status, 'Gaviota mediana de alas blanquecinas sin puntas negras, pico rojo coral y capucha negra completa en primavera. En vuelo destaca por sus primarias sin marcas oscuras, un rasgo que la separa de la reidora aun de lejos.' description, 'Alas blancas sin puntas negras, muy pálidas en vuelo; Pico rojo intenso y grueso, con anillo ocular blanco; Capucha negra completa en primavera; mancha en la oreja en invierno' identification_tips, 'Otoño e invierno, con paso en primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Larus_melanocephalus_aka_Mediterranean_Gull_rare_guest_in_Sweden2.jpg?width=1280' image_url, 'Martin Olsson (mnemo on en/sv wikipedia and commons, martin@minimum… (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Sin ocurrencia de GBIF verificada dentro del espacio: la cita es documental.' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, 'Charadriiformes' taxon_order, 'Laridae' taxon_family, 'Larus' taxon_genus, 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)' iucn_global, 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011) · Anexo IV (Ley 42/2007, de 13 de diciembre, del Patrimonio Natural y de la Biodiversidad. BOE 299, de 14 de diciembre de 2007)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 14050 eidos_taxonid, NULL gbif_species_key,