    SELECT 'Gaviota reidora' common_name, 'Chroicocephalus ridibundus' scientific_name, 'fauna' kingdom, 'Ave marina' family, 'Costas, salinas, embalses, ríos y campos de cultivo inundados' primary_habitat, 'Anexo III' conservation_status, 'Gaviota pequeña y ágil, muy común en invierno tierra adentro. En verano lleva la cabeza cubierta por una capucha de color chocolate; en invierno solo le queda una mancha oscura tras el ojo. En vuelo enseña una cuña blanca inconfundible en el borde delantero del ala.' description, 'Cuña blanca en el filo delantero del ala, visible en vuelo; En invierno, una mancha oscura como un auricular tras el ojo; Pico y patas rojo oscuro' identification_tips, 'Otoño e invierno' seasonality, 'https://inaturalist-open-data.s3.amazonaws.com/photos/605325270/original.jpg' image_url, 'lalaia (CC BY 4.0) · GBIF' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Confirmada además por 144 ocurrencias de GBIF dentro de este espacio. La lista oficial la cita como Larus ridibundus; EIDOS (IEPNB) acepta Chroicocephalus ridibundus.' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, NULL taxon_order, NULL taxon_family, 'Chroicocephalus' taxon_genus, 'LC (Preocupación menor)' iucn_global, 'Directiva Aves 2009/147/CE (Red Natura 2000)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 16356 eidos_taxonid, NULL gbif_species_key, 'ES0000507' zepa_site_code
    UNION ALL
    SELECT 'Alcatraz atlántico' common_name, 'Morus bassanus' scientific_name, 'fauna' kingdom, 'Ave marina' family, 'Mar abierto y aguas costeras en invierno' primary_habitat, 'Protegida (LESRPE)' conservation_status, 'Ave marina grande y blanca con las puntas de las alas negras y la cabeza teñida de amarillo, de silueta afilada como una lanza. Pesca lanzándose en picado desde decenas de metros y entrando en el agua como un arpón, en zambullidas que se ven desde la costa.' description, 'Silueta blanca en cruz, con las puntas de las alas negras; Zambullidas verticales espectaculares desde gran altura; Cabeza y cuello con tinte amarillento en los adultos' identification_tips, 'Otoño e invierno' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Morus_bassanus_adu.jpg?width=1280' image_url, 'Andreas Trepte (CC BY-SA 2.5) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Confirmada además por 48 ocurrencias de GBIF dentro de este espacio.' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, 'Suliformes' taxon_order, 'Sulidae' taxon_family, 'Morus' taxon_genus, 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)' iucn_global, 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 14031 eidos_taxonid, NULL gbif_species_key, 'ES0000507' zepa_site_code
