    SELECT 'Págalo parásito' common_name, 'Stercorarius parasiticus' scientific_name, 'fauna' kingdom, 'Ave marina' family, 'Mar abierto y aguas costeras durante los pasos migratorios' primary_habitat, 'Protegida (LESRPE)' conservation_status, 'Ave marina de vuelo rápido y ágil, con aspecto de gaviota estilizada y las dos plumas centrales de la cola alargadas en punta. Se alimenta persiguiendo a charranes y gaviotas hasta obligarlos a soltar la presa, un comportamiento llamado cleptoparasitismo.' description, 'Persigue a otras aves marinas en vuelo, acosándolas; Dos plumas centrales de la cola alargadas y puntiagudas; Manchas blancas en la base de las primarias, visibles en vuelo' identification_tips, 'Pasos de primavera y otoño' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Arctic_skua_(Stercorarius_parasiticus)_on_an_ice_floe%2C_Svalbard.jpg?width=1280' image_url, 'AWeith (CC BY-SA 4.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Sin ocurrencia de GBIF verificada dentro del espacio: la cita es documental.' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, 'Charadriiformes' taxon_order, 'Stercorariidae' taxon_family, 'Stercorarius' taxon_genus, 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)' iucn_global, 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 14042 eidos_taxonid, NULL gbif_species_key, 'ES0000507' zepa_site_code
