    SELECT 'Págalo pomarino' common_name, 'Stercorarius pomarinus' scientific_name, 'fauna' kingdom, 'Ave marina' family, 'Mar abierto, en paso migratorio frente a las costas' primary_habitat, 'Protegida (LESRPE)' conservation_status, 'Págalo grande y robusto, de pecho ancho y vuelo potente, con las plumas centrales de la cola ensanchadas y retorcidas en cuchara cuando es adulto. Como sus parientes, roba comida a otras aves marinas y sigue a los barcos de pesca.' description, 'Plumas centrales de la cola anchas y retorcidas en el adulto; Cuerpo pesado y pecho ancho, más que en el págalo parásito; Vuelo directo y potente, con aleteo profundo' identification_tips, 'Pasos de otoño y primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stercorarius_pomarinusPCCA20070623-3985B.jpg?width=1280' image_url, 'Patrick Coin (Patrick Coin) (CC BY-SA 2.5) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 2 rarity_score, FALSE is_featured, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Sin ocurrencia de GBIF verificada dentro del espacio: la cita es documental.' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, 'Charadriiformes' taxon_order, 'Stercorariidae' taxon_family, 'Stercorarius' taxon_genus, 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)' iucn_global, 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, 14041 eidos_taxonid, NULL gbif_species_key, 'ES0000507' zepa_site_code
