    SELECT 'Charrán común' common_name, 'Sterna hirundo' scientific_name, 'fauna' kingdom, 'Ave marina' family, 'Costas, salinas, deltas y lagunas litorales' primary_habitat, 'Sensible a la alteración de su hábitat' conservation_status, 'Charrán esbelto de alas estrechas y cola muy ahorquillada, gris pálido por encima, con capirote negro y pico rojo de punta oscura. Pesca cerniéndose sobre el agua y lanzándose en picado corto, y su reclamo áspero delata las colonias a distancia.' description, 'Pico rojo con la punta negra en primavera y verano; Cola muy ahorquillada, con las plumas externas largas; Se cierne y se lanza en picado corto sobre el agua' identification_tips, 'De primavera a otoño' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Charr%C3%A1n_Com%C3%BAn_(Sterna_hirundo_hirundo)_in_Canary_Islands.jpg?width=1280' image_url, 'Juan Emilio from Las Palmas de Gran Canaria, España (CC BY-SA 2.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 3 rarity_score, FALSE is_featured, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Sin ocurrencia de GBIF verificada dentro del espacio: la cita es documental.' source, 'Chordata' taxon_phylum, 'Aves' taxon_class, 'Charadriiformes' taxon_order, 'Laridae' taxon_family, 'Sterna' taxon_genus, 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)' iucn_global, 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011) · Anexo IV (Ley 42/2007, de 13 de diciembre, del Patrimonio Natural y de la Biodiversidad. BOE 299, de 14 de diciembre de 2007)' spain_status, 'Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)' murcia_status, 14079 eidos_taxonid, NULL gbif_species_key, 'ES